import { useState, useEffect } from "react"
import "../defaultresort/roomcarts.css"

const AllRoomsList = () => {

    let [ store, setStore ] = useState([]);

    const getdata = () => {
        try{
            fetch("http://localhost:1234/room")
            .then( res => res.json() )
            .then( info => {
                setStore(info)
            })
        }catch(error){
            console.error(" Data fetching is not processed ")
        }
    }

    useEffect( () => {
        getdata()
    }, [])

    const handelinput = (rooms) => {

        const inputes = window.prompt(" Enter your Email Id ");

        const roomdetails = {
            "email" : inputes,
            "rooms" : rooms
        }

        const url = "http://localhost:1111/main/"
        const postdata = {
            headers : { 'Content-type' : 'application/json' },
            method  : 'post',
            body    : JSON.stringify( roomdetails )
        }

        // console.log(postdata);

        try{ 

            fetch(url, postdata)
            .then( res => res.json() )
            .then( info => {
                alert( info.infos )
            })
        }catch(error){
            console.log(" Data process failed.... ");
        }

    }

    return(
        <>
            <div className="container" >
                <h2 className="fw-bolder m ms-md-4" > LIST OF ROOM AVAILABLE </h2>
                    <div className="row" >

                        {
                            store.map( ( value, index ) => {
                                return(
                                    <div className="col-md-4 mt-4" key={index}>
                                        <div className=" card hovers rounded-5"  >
                                            <img src={value.image} alt="images" className=" p-2 rounded-5" />
                                            <div className=" card-body " >
                                                <h3 className="card-title fw-bold"> Room : {value.rooms} </h3>
                                                <div> 1hr/50m <br/> Tue 18/2 to Sat 22/2  </div> 
                                                <h3 className=" fw-bold " > from : $ 200 </h3>
                                                <button className="btn btn-primary mt-2" onClick={(obj) => handelinput(value.rooms)} > Book </button>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })
                        }
                    </div>
            </div>       
        </>
    )
}

export default AllRoomsList
